  var aktiv = '';
  function filterAusHash() { var m = /(?:^#|&)f=([^&]*)/.exec(location.hash); try { return m ? decodeURIComponent(m[1]) : ''; } catch (e) { return ''; } }
  function anwenden() {
    var q = feld ? feld.value.trim().toLowerCase() : '';
