// Der Erledigt-Knopf schickt ID und Token der Aufgabe. Das Token kennt nur die Arbeitsliste selbst: Eine fremde Webseite
// kann es nicht erraten und deshalb keine Aufgabe im Namen des Einkäufers erledigen. Die Herkunft des Browsers lässt sich
// nicht prüfen, weil n8n die Seite in einer Sandbox ausliefert (Origin: null).
const id = Number($json.body?.id);
const token = String($json.body?.token ?? '');
// Nur ein einfacher Filter-Anker darf zurück in die Adresse, damit nichts in die Kopfzeile der Antwort gelangt.
const rueck = /^#[A-Za-z0-9_=%.-]{0,80}$/.test(String($json.body?.rueck ?? '')) ? String($json.body.rueck) : '';
return { json: { gueltig: Number.isInteger(id) && id > 0 && /^[0-9a-f]{64}$/.test(token), id, token, rueck } };
